    &lt;div class="produto"&gt;
        &lt;h2&gt;Mouse&lt;/h2&gt;
        &lt;p class="preco"&gt;R$ 50,00&lt;/p&gt;
    &lt;/div&gt;
    &lt;p class="preco"&gt;Preço especial: R$ 100,00&lt;/p&gt;
&lt;/body&gt;
&lt;/html&gt;
"""

precos = extrair_por_classe(html_exemplo, 'preco')
print("Preços encontrados:")
for i, preco in enumerate(precos, 1):
