8. Coletor de Imagens
from bs4 import BeautifulSoup

def coletar_imagens(html):
    """Coleta todas as imagens e seus atributos alt"""
    soup = BeautifulSoup(html, 'html.parser')
    imagens = soup.find_all('img')

    resultado = []
    for img in imagens:
        resultado.append({
            'src': img.get('src', ''),
            'alt': img.get('alt', ''),
            'title': img.get('title', '')
        })

    return resultado

# Exemplo de uso
